import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Register.css';

function Register() {
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    agree: false
  });

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Register:', form);
  };

  return (
    <div className="register-page">
      <div className="register-container">
        <div className="register-header">
          <h1>Gabung WORKIE</h1>
          <p>Mulai dapatkan pekerjaan instan atau rekrut pekerja terlatih hari ini.</p>
        </div>

        <form className="register-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Nama Lengkap</label>
            <input
              name="name"
              placeholder="Contoh: Andi Wijaya"
              value={form.name}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label>Email</label>
            <input
              name="email"
              type="email"
              placeholder="Contoh: andi@gmail.com"
              value={form.email}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label>Nomor HP</label>
            <input
              name="phone"
              placeholder="Contoh: 08123456789"
              value={form.phone}
              onChange={handleChange}
            />
          </div>

          <div className="form-group">
            <label>Kata Sandi</label>
            <input
              name="password"
              type="password"
              placeholder="Minimal 8 karakter"
              value={form.password}
              onChange={handleChange}
            />
          </div>

          <div className="form-group checkbox">
            <input
              name="agree"
              type="checkbox"
              checked={form.agree}
              onChange={handleChange}
            />
            <label>
              Saya menyetujui Syarat & Ketentuan serta Kebijakan Privasi WORKIE.
            </label>
          </div>

          <button type="submit" className="btn-primary">Daftar</button>
        </form>

        <div className="login-link">
          Sudah punya akun? <Link to="/">Masuk</Link>
        </div>
      </div>
    </div>
  );
}

export default Register;
